-- Fleeto Tertiary Invoice: additive greenfield/integration-ready schema.
create extension if not exists pgcrypto;
create type public.app_role as enum ('SUPER_ADMIN','ADMIN','MANAGER','DEALER');
create type public.inventory_status as enum ('AVAILABLE','RESERVED','SOLD','RETURNED','DAMAGED','BLOCKED');
create type public.invoice_status as enum ('DRAFT','GENERATED','PAID','CANCELLED');
create table if not exists public.user_profiles(id uuid primary key references auth.users(id) on delete cascade, role app_role not null default 'DEALER', dealer_id uuid, display_name text, created_at timestamptz not null default now());
create table if not exists public.ui_sections(id uuid primary key default gen_random_uuid(), section_key text unique not null, display_name text not null, route text, sort_order int not null default 0, is_enabled boolean not null default true, settings jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table if not exists public.ui_fields(id uuid primary key default gen_random_uuid(), section_id uuid not null references public.ui_sections(id) on delete cascade, field_key text not null, display_name text not null, field_type text not null, sort_order int not null default 0, is_visible boolean not null default true, is_system boolean not null default false, options jsonb not null default '[]'::jsonb, settings jsonb not null default '{}'::jsonb, unique(section_id,field_key));
create table if not exists public.validation_rules(id uuid primary key default gen_random_uuid(), field_id uuid not null references public.ui_fields(id) on delete cascade, rule_type text not null, rule_value jsonb not null default '{}'::jsonb, error_message text, is_active boolean not null default true, priority int not null default 100, updated_by uuid references auth.users(id), updated_at timestamptz not null default now());
create table if not exists public.theme_settings(id uuid primary key default gen_random_uuid(), scope text unique not null default 'GLOBAL', primary_color text not null default '#D71920', secondary_color text not null default '#101114', surface_color text not null default '#FFFFFF', font_family text not null default 'Inter', heading_font_family text not null default 'Inter', radius text not null default '18px', tokens jsonb not null default '{}'::jsonb, updated_by uuid references auth.users(id), updated_at timestamptz not null default now());
create table if not exists public.audit_logs(id bigint generated always as identity primary key, actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id text, old_data jsonb, new_data jsonb, created_at timestamptz not null default now());
create table if not exists public.tax_config(id uuid primary key default gen_random_uuid(), code text unique not null, gst numeric(7,4) not null, cgst numeric(7,4) not null, sgst numeric(7,4) not null, active_from date not null, active_to date, is_active boolean not null default true);
create table if not exists public.invoice_number_config(id uuid primary key default gen_random_uuid(), scope_key text unique not null, pattern text not null default '{DEALER}/{FY}/{SEQ6}', next_number bigint not null default 1, updated_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_profiles p where p.id=auth.uid() and p.role in ('SUPER_ADMIN','ADMIN')) $$;
create or replace function public.is_super_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_profiles p where p.id=auth.uid() and p.role='SUPER_ADMIN') $$;
alter table public.ui_sections enable row level security;alter table public.ui_fields enable row level security;alter table public.validation_rules enable row level security;alter table public.theme_settings enable row level security;alter table public.audit_logs enable row level security;
create policy "config read authenticated" on public.ui_sections for select to authenticated using(true);create policy "config admin write" on public.ui_sections for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "fields read authenticated" on public.ui_fields for select to authenticated using(true);create policy "fields admin write" on public.ui_fields for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "rules read authenticated" on public.validation_rules for select to authenticated using(true);create policy "rules admin write" on public.validation_rules for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "theme read authenticated" on public.theme_settings for select to authenticated using(true);create policy "theme admin write" on public.theme_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "audit admin read" on public.audit_logs for select to authenticated using(public.is_admin());
insert into public.theme_settings(scope) values('GLOBAL') on conflict(scope) do nothing;
insert into public.tax_config(code,gst,cgst,sgst,active_from) values('GST_2W',5,2.5,2.5,current_date) on conflict(code) do nothing;
